        });

        bytes32 orderHash = c.hashOrder(order);
        bool cancelledBefore = c.cancelledOrders(orderHash);

        bool reverted;
        if (msg.sender == maker) {
            try c.cancel(order) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.cancel(order) {
                reverted = false;
            } catch {
                reverted = true;
            }
