contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address owner,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) public {
        uint256 nonceBefore = c.nonces(owner);
        uint256 allowanceBefore = c.allowance(owner, spender);

        bool reverted;
        try c.permit(owner, spender, value, deadline, v, r, s) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 nonceAfter = c.nonces(owner);
        uint256 allowanceAfter = c.allowance(owner, spender);

        if (reverted) {
            assert(nonceAfter == nonceBefore && allowanceAfter == allowanceBefore);
        } else {
            assert(nonceAfter == nonceBefore + 1);
            assert(allowanceAfter == value);
        }
    }
}

